package autopoiesis

import (
	"context"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"

	"codenerd/internal/logging"
)

// toolIOType is the sole type the Ouroboros pipeline can compile and execute.
// The compiler's entry-point contract in tool_compiler.go:isExactEntryPoint
// accepts only func(context.Context, string) (string, error), and the wrapper
// generated by writeWrapper reads a string input from stdin/args and writes a
// string output as JSON. Any other choice from the model cannot be carried by
// the wrapper and will fail compilation with "no suitable entry point function
// found with signature 'func(context.Context, string) (string, error)'".
// Constraining here — the single place a ToolNeed is built from the LLM's
// JSON — ensures every downstream generation path (JIT and legacy in
// tool_generation.go) inherits the correct contract instead of each path
// re-checking.
const toolIOType = "string"

// coerceToolIOType enforces the compiler contract on a single I/O slot.
// It always returns toolIOType ("string"), logging at debug level when the
// model's requested type is overridden so the coercion is observable rather
// than silent.
func coerceToolIOType(raw, field string) string {
	if raw != toolIOType {
		if raw != "" {
			logging.AutopoiesisDebug("coercing ToolNeed %s from %q to %q: compiler entry point requires func(context.Context, string) (string, error) and writeWrapper only supports string I/O", field, raw, toolIOType)
		}
		return toolIOType
	}
	return raw
}

// coerceToolNeedTypes normalizes both I/O fields of a ToolNeed in place to
// the compiler contract. This is the single enforcement point so every
// downstream generation path inherits the same string contract and the two
// construction paths (LLM result and heuristic fallback in DetectToolNeed)
// remain consistent.
func coerceToolNeedTypes(need *ToolNeed) {
	if need == nil {
		return
	}
	need.InputType = coerceToolIOType(need.InputType, "input_type")
	need.OutputType = coerceToolIOType(need.OutputType, "output_type")
}

// ToolNeed represents a detected need for a new tool
type ToolNeed struct {
	Name       string   // Proposed tool name
	Purpose    string   // What the tool should do
	InputType  string   // Expected input type
	OutputType string   // Expected output type
	Triggers   []string // What user inputs suggest this need
	Priority   float64  // How urgently this is needed (0.0 - 1.0)
	Confidence float64  // How confident we are this is a real need
	Reasoning  string   // Why we think this tool is needed
}

// Tool need detection patterns
// Note: missingCapabilityPatterns is defined in autopoiesis_helpers.go
var (
	// Patterns suggesting specific tool types
	toolTypePatterns = map[string][]*regexp.Regexp{
		"validator": {
			regexp.MustCompile(`(?i)validate\s+(the\s+)?(json|yaml|xml|config|schema|format)`),
			regexp.MustCompile(`(?i)check\s+(if|whether)\s+.+\s+(is\s+)?(valid|correct|proper)`),
		},
		"converter": {
			regexp.MustCompile(`(?i)convert\s+(from\s+)?(\w+)\s+to\s+(\w+)`),
			regexp.MustCompile(`(?i)transform\s+.+\s+(into|to)\s+`),
		},
		"parser": {
			regexp.MustCompile(`(?i)parse\s+(the\s+)?(\w+)\s+(file|data|output|response)`),
			regexp.MustCompile(`(?i)extract\s+.+\s+from\s+`),
		},
		"analyzer": {
			regexp.MustCompile(`(?i)analyze\s+(the\s+)?(\w+)\s+(for|to\s+find)`),
			regexp.MustCompile(`(?i)find\s+(all|every)\s+.+\s+in\s+`),
		},
		"formatter": {
			regexp.MustCompile(`(?i)format\s+(the\s+)?(\w+)\s+(as|like|to)`),
			regexp.MustCompile(`(?i)pretty\s*print\s+`),
		},
	}
)

// DetectToolNeed analyzes input to determine if a new tool is needed
func (tg *ToolGenerator) DetectToolNeed(ctx context.Context, input string, failedAttempt string) (*ToolNeed, error) {
	timer := logging.StartTimer(logging.CategoryAutopoiesis, "DetectToolNeed")
	defer timer.Stop()

	logging.AutopoiesisDebug("Detecting tool need from input (%d chars)", len(input))

	lower := strings.ToLower(input)

	// Whether this is a capability gap is the kernel's decision over Jev's
	// judgments, with the capability patterns as fallback evidence
	// (tool_need.go). A failed attempt alone is never a gap.
	decision := tg.decideToolGap(ctx, input, failedAttempt)
	if !decision.gap {
		logging.AutopoiesisDebug("No tool need: the kernel derived no capability gap (source %s)", decision.source)
		return nil, nil
	}
	triggers := []string{"tool_gap_observed/" + decision.source}
	logging.Autopoiesis("Tool need: the kernel derived a capability gap (source %s)", decision.source)

	// The tool kind is a hint for the spec writer: Jev's when it answered,
	// else the patterns'.
	toolType := decision.kind
	if toolType == "" {
		toolType = toolTypeByPattern(lower)
	}
	logging.AutopoiesisDebug("Detected tool type: %s", toolType)

	// Use LLM to refine the tool need
	logging.Autopoiesis("Refining tool need with LLM for type=%s", toolType)
	need, err := tg.refineToolNeedWithLLM(ctx, input, failedAttempt, toolType, triggers)
	if err != nil {
		logging.Get(logging.CategoryAutopoiesis).Warn("LLM refinement failed: %v, using heuristic fallback", err)
		// Fall back to heuristic-based need. Use the single string contract
		// constant so both the LLM and fallback paths always produce the same
		// compiler-compatible ToolNeed (see toolIOType / coerceToolNeedTypes).
		fallback := &ToolNeed{
			Name:       fmt.Sprintf("%s_tool", toolType),
			Purpose:    input,
			InputType:  toolIOType,
			OutputType: toolIOType,
			Triggers:   triggers,
			Priority:   0.5,
			Confidence: 0.4,
			Reasoning:  "Detected via pattern matching, LLM refinement failed",
		}
		coerceToolNeedTypes(fallback)
		return fallback, nil
	}

	logging.Autopoiesis("Tool need refined: name=%s, confidence=%.2f", need.Name, need.Confidence)
	return need, nil
}

// toolTypeByPattern is the tool kind from toolTypePatterns, in a fixed order
// so the same input always gets the same kind; "utility" when none matches.
func toolTypeByPattern(lower string) string {
	for _, ttype := range []string{"validator", "converter", "parser", "analyzer", "formatter"} {
		for _, pattern := range toolTypePatterns[ttype] {
			if pattern.MatchString(lower) {
				return ttype
			}
		}
	}
	return "utility"
}

// refineToolNeedWithLLM uses LLM to better understand the tool need
func (tg *ToolGenerator) refineToolNeedWithLLM(ctx context.Context, input, failedAttempt, toolType string, triggers []string) (*ToolNeed, error) {
	prompt := fmt.Sprintf(`codeNERD's kernel has found a capability gap in this request that a new tool will fill. Write the tool's spec.

User Request: %q
Previous Attempt Failed: %q
Tool Kind: %s
Why the kernel found a gap: %v

Existing tools available (do not duplicate them): %v

Return JSON only:
{
  "tool_name": "snake_case_name",
  "purpose": "clear description of what the tool should do",
  "input_type": "go type for input (string, []byte, map[string]any, etc)",
  "output_type": "go type for output",
  "priority": 0.0-1.0,
  "confidence": 0.0-1.0,
  "reasoning": "why this tool is needed"
}

JSON only:`, input, failedAttempt, toolType, triggers, tg.listExistingTools())

	resp, err := tg.client.Complete(ctx, prompt)
	if err != nil {
		return nil, err
	}

	// Parse response
	var result struct {
		ToolName   string  `json:"tool_name"`
		Purpose    string  `json:"purpose"`
		InputType  string  `json:"input_type"`
		OutputType string  `json:"output_type"`
		Priority   float64 `json:"priority"`
		Confidence float64 `json:"confidence"`
		Reasoning  string  `json:"reasoning"`
	}

	// Extract JSON from response
	jsonStr := extractJSON(resp)
	if err := json.Unmarshal([]byte(jsonStr), &result); err != nil {
		return nil, fmt.Errorf("failed to parse LLM response: %w", err)
	}

	need := &ToolNeed{
		Name:       result.ToolName,
		Purpose:    result.Purpose,
		InputType:  result.InputType,
		OutputType: result.OutputType,
		Triggers:   triggers,
		Priority:   result.Priority,
		Confidence: result.Confidence,
		Reasoning:  result.Reasoning,
	}
	// Enforce the compiler's string contract so every downstream generation
	// path inherits the same correct signature. isExactEntryPoint in
	// tool_compiler.go accepts only func(context.Context, string) (string, error)
	// and writeWrapper can only marshal string input/output.
	coerceToolNeedTypes(need)
	return need, nil
}
